def is_valid_us_date(s):
    fields = s.split('/')
    if len(fields) != 3:
        return False
    mm, dd, yyyy = fields
    if not (mm.isdigit() and dd.isdigit() and yyyy.isdigit()):
        return False
    if len(mm) != 2 or len(dd) != 2 or len(yyyy) != 4:
        return False
    m, d, y = int(mm), int(dd), int(yyyy)
    if not 1 <= m <= 12:
        return False
    def is_leap(year):
        return year % 400 == 0 or (year % 4 == 0 and year % 100 != 0)
    month_lengths = {1: 31, 2: 28, 3: 31, 4: 30, 5: 31, 6: 30,
                      7: 31, 8: 31, 9: 30, 10: 31, 11: 30, 12: 31}
    max_day = 29 if (m == 2 and is_leap(y)) else month_lengths[m]
    return 1 <= d <= max_day

