def is_valid_stopwatch_time(s):
    parts = s.split(':')
    if len(parts) != 2:
        return False
    minutes, seconds = parts
    if not minutes or not seconds:
        return False
    if not all(ch in '0123456789' for ch in minutes + seconds):
        return False
    if len(seconds) != 2:
        return False
    if len(minutes) > 1 and minutes[0] == '0':
        return False
    return int(seconds) < 60

